mapper.select:
SELECT 
    COUNT(*) AS total_count,
    SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END) AS total_income,
    SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END) AS total_expense,
    SUM(CASE WHEN type = 'income' THEN amount ELSE 0 END) - SUM(CASE WHEN type = 'expense' THEN amount ELSE 0 END) AS net_amount
FROM accounts
WHERE 1=1

    AND project_id = #{projectId}


    AND transaction_date >= #{startDate}


    AND transaction_date <= #{endDate}

SELECT a.*, pa.name as payment_account_name, pa.balance as payment_account_balance, p.project_name, sc.contract_name
FROM accounts a
LEFT JOIN payment_account pa ON a.payment_account_id = pa.id
LEFT JOIN projects p ON a.project_id = p.id
LEFT JOIN subcontractor_contracts sc ON a.contract_id = sc.id
WHERE 1=1

    AND a.project_id = #{projectId}


    AND a.type = #{type}


    AND a.transaction_date >= #{startDate}


    AND a.transaction_date <= #{endDate}

LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM accounts a
LEFT JOIN payment_account pa ON a.payment_account_id = pa.id
LEFT JOIN projects p ON a.project_id = p.id
WHERE 1=1

    AND a.project_id = #{projectId}


    AND a.type = #{type}


    AND a.transaction_date >= #{startDate}


    AND a.transaction_date <= #{endDate}
